fn append(a: &Vec<i32>, b: i32) -> Vec<i32> {
    // Preallocate a new vector with one extra slot
    let mut result = Vec::with_capacity(a.len() + 1);
    // Copy all elements from `a`
    result.extend_from_slice(a);
    // Append `b` at the end
    result.push(b);
    result
}

